const raw = $input.all();

let msgs;
if (raw.length === 1 && Array.isArray(raw[0].json.messages)) {
  msgs = raw[0].json.messages;
} else {
  msgs = raw.map((i) => i.json);
}

const seen = new Set();
const rows = msgs
  .map((m) => {
    const msg = m.message || {};
    const body =
      msg.conversation ||
      (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
      (msg.imageMessage && msg.imageMessage.caption) ||
      (msg.videoMessage && msg.videoMessage.caption) ||
      (msg.documentMessage && msg.documentMessage.caption) ||
      (msg.contactMessage && msg.contactMessage.displayName) ||
      (msg.audioMessage ? '[audio]' : '') ||
      (msg.stickerMessage ? '[figurinha]' : '') ||
      (msg.locationMessage ? '[localizacao]' : '') ||
      '';
    const ts = Number(m.messageTimestamp);
    const mid = (m.key && m.key.id) || ((m.key && m.key.remoteJid) + '_' + ts);
    return { ts: isFinite(ts) ? ts : 0, fromMe: !!(m.key && m.key.fromMe), body, mid };
  })
  .filter((r) => r.body && r.ts > 0 && !seen.has(r.mid) && (seen.add(r.mid), true))
  .sort((a, b) => a.ts - b.ts);

const transcript = rows
  .map((r) => (r.fromMe ? 'Eu' : 'Contato') + ': ' + r.body)
  .join('\n');

const toIso = (ts) => (ts ? new Date(ts * 1000).toISOString() : null);

return [
  {
    json: {
      transcript,
      first_message_at: toIso(rows.length ? rows[0].ts : null),
      last_message_at: toIso(rows.length ? rows[rows.length - 1].ts : null),
      checkpoint: toIso(rows.length ? rows[rows.length - 1].ts : null),
    },
  },
];
